/// Read an unaligned little-endian material word by bank-$01 address.
pub fn word_at(address: u16) -> Option<u16> {
    let offset = usize::from(address.checked_sub(COLOR_TABLE_ROM_OFF as u16)?);
    let bytes = COLOR_DATA.get(offset..offset + 2)?;
    Some(u16::from_le_bytes([bytes[0], bytes[1]]))
}

/// Resolve a face index through its exact ShapeHdr color-table pointer.
pub fn material_at(table_address: u16, face_color_index: u8) -> Option<u16> {
    word_at(table_address.checked_add(u16::from(face_color_index) * 2)?)
}

/// Follow SF2's bank-$01 COLANIM records for the object's color frame.
pub fn resolve_animated_material(mut material: u16, col_frame: u8) -> Option<u16> {
    for _ in 0..4 {
        if material & 0xC000 != 0x8000 {
            return Some(material);
        }
        let record = 0x8000 | (material & 0x3FFF);
        let offset = usize::from(record.checked_sub(COLOR_TABLE_ROM_OFF as u16)?);
        let &count = COLOR_DATA.get(offset)?;
        if count == 0 || count > 64 || !count.is_power_of_two() {
            return None;
        }
        let frame = usize::from(col_frame & (count - 1));
        let bytes = COLOR_DATA.get(offset + 1 + frame * 2..offset + 3 + frame * 2)?;
        material = u16::from_le_bytes([bytes[0], bytes[1]]);
    }
    None
}
